<script lang="ts">
 import {onMount,tick} from 'svelte';import PinButton from './PinButton.svelte';import {pinnedFirst,type PinTarget} from '$lib/blux/pins';import type {DeletionTarget} from '$lib/blux/deletion';import {request,errorText} from '$lib/blux/api';import type {Collaboration,SharedSnapshot} from '$lib/blux/collaborations';import {statusLabels} from '$lib/blux/collaborations';import type {AgentInfo} from '$lib/blux/agents';import {agentName,agentOptions} from '$lib/blux/agents';import {folderName} from '$lib/blux/context';import Select from './Select.svelte';import Icon from './Icon.svelte';import AgentBadge from './AgentBadge.svelte';import CollaborationDialog from './CollaborationDialog.svelte';import PublicArtifacts from './PublicArtifacts.svelte';
 export let onPin:(target:PinTarget)=>void=()=>{};export let pinning=new Set<string>();
 export let onDelete:(target:DeletionTarget)=>void=()=>{};
 export let list:Collaboration[]=[];export let selectedID='';export let project='';export let agents:AgentInfo[]=[];export let onSelect:(id:string)=>void=()=>{};export let onTask:(id:string)=>void=()=>{};export let onRefresh:()=>void=()=>{};export let createRequested=0;export let loadError='';export let ready=false;
 let error='';let search='';let status='';let executor='';let createOpen=false;let taskOpen=false;let tab='artifacts';let snapshots:SharedSnapshot[]=[];let taskFilter='';let loadedID='';let alive=true;let epoch=0;let previousRequested=0;
 $: collaboration=list.find(v=>v.id===selectedID)||null;
 $: visibleSnapshots=snapshots.filter(v=>collaboration?.tasks.some(t=>t.id===v.task_id));
 $: filtered=pinnedFirst(list.filter(v=>(!status||v.status===status)&&(!executor||v.tasks.some(t=>t.adapter===executor))&&`${v.title} ${v.goal}`.toLowerCase().includes(search.toLowerCase())),v=>v.created_at);
 $: if(createRequested!==previousRequested){previousRequested=createRequested;void tick().then(()=>createOpen=true);}
 $: if(selectedID!==loadedID){loadedID=selectedID;snapshots=[];taskFilter='';tab='artifacts';void refreshArtifacts(selectedID);}
 async function refreshArtifacts(id:string){const ticket=++epoch;if(!id)return;try{const v=await request<{snapshots:SharedSnapshot[]}>(`/collaborations/${id}/artifacts`);if(alive&&ticket===epoch){snapshots=v.snapshots;error='';}}catch(e){if(alive&&ticket===epoch)error=errorText(e)}}
 onMount(()=>{alive=true;const timer=setInterval(()=>{onRefresh();void refreshArtifacts(selectedID)},2000);return()=>{alive=false;epoch++;clearInterval(timer)}});
 function created(id:string){onRefresh();onSelect(id)}
 function taskCreated(){onRefresh();void refreshArtifacts(selectedID)}
 $: if(taskFilter&&collaboration&&!collaboration.tasks.some(t=>t.id===taskFilter)){taskFilter='';void refreshArtifacts(selectedID);}
 $: activities=collaboration?[...collaboration.tasks].sort((a,b)=>b.updated_at.localeCompare(a.updated_at)):[];
</script>
{#if loadError}<div class="inline-error collaboration-fetch-error" role="alert">{loadError}<button on:click={onRefresh}>重试</button></div>{/if}
{#if !selectedID}
 <div class="collaboration-list-page"><header class="section-heading"><div><h1>Agent 协作</h1></div><div class="section-heading-actions"><button class="primary-button" on:click={()=>createOpen=true}><Icon name="plus" size={17}/>新建协作</button></div></header>
  <div class="collaboration-filters"><div class="filter-search"><Icon name="search" size={17}/><input aria-label="搜索协作" bind:value={search} placeholder="搜索协作任务"/></div><Select ariaLabel="协作状态" bind:value={status} options={[{value:'',label:'全部状态'},{value:'running',label:'进行中'},{value:'completed',label:'已完成'},{value:'pending',label:'待开始'},{value:'attention',label:'需要处理'}]}/><Select ariaLabel="筛选 Agent" bind:value={executor} options={[{value:'',label:'全部 Agent'},...agentOptions([],true)]}/></div>
  {#if error}<p role="alert" class="inline-error">{error}</p>{/if}
  <div class="collaboration-table"><div class="collaboration-table-head"><span>协作任务名称</span><span>状态</span><span>执行 Agent</span><span>公共产物</span><span>最近更新</span></div>
   {#each filtered as item}<div class="collaboration-table-entry"><button class="collaboration-table-row" on:click={()=>onSelect(item.id)}><span class="collaboration-name"><strong>{item.title}</strong></span><span class="status-pill" class:running={item.status==='running'} class:complete={item.status==='completed'}>{statusLabels[item.status]||item.status}</span><span class="collaboration-agent-list">{#each [...new Set(item.tasks.map(t=>t.adapter))] as adapter}<AgentBadge {adapter}/>{/each}{#if !item.tasks.length}<span class="muted">尚未分配</span>{/if}</span><span class="muted">{item.artifact_count} 个文件</span><span class="muted">{new Date(item.updated_at).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})}</span></button><div class="list-item-actions"><PinButton kind="collaboration" id={item.id} title={item.title} pinned={!!item.pinned_at} disabled={pinning.has(`collaboration:${item.id}`)} {onPin}/><button class="ui-icon-button item-delete-button" aria-label={`删除协作：${item.title}`} on:click={()=>onDelete({kind:'collaboration',id:item.id,title:item.title})}><Icon name="trash" size={16}/></button></div></div>{/each}
  </div>
  {#if !filtered.length}<div class="collaboration-empty"><Icon name="team" size={32}/><h2>{search||status||executor?'没有匹配的协作':'创建你的第一个 Agent 协作'}</h2>{#if !list.length}<button class="subtle-button" on:click={()=>createOpen=true}>新建协作 <Icon name="plus" size={15}/></button>{/if}</div>{/if}
 </div>
{:else if collaboration}
 <div class="collaboration-detail"><section class="collaboration-center"><header class="collaboration-title-bar"><button class="ui-icon-button" aria-label="返回协作列表" on:click={()=>onSelect('')}><Icon name="back"/></button><h1>{collaboration.title}</h1><span class="status-pill" class:running={collaboration.status==='running'}>{statusLabels[collaboration.status]}</span><PinButton kind="collaboration" id={collaboration.id} title={collaboration.title} pinned={!!collaboration.pinned_at} disabled={pinning.has(`collaboration:${collaboration.id}`)} {onPin}/><button class="ui-icon-button" aria-label="删除当前协作" on:click={()=>onDelete({kind:'collaboration',id:collaboration.id,title:collaboration.title})}><Icon name="trash" size={17}/></button></header>
  <nav class="collaboration-tabs" aria-label="协作内容"><button class:active={tab==='artifacts'} aria-current={tab==='artifacts'?'page':undefined} on:click={()=>tab='artifacts'}>公共产物</button><button class:active={tab==='activity'} on:click={()=>tab='activity'}>动态</button><button class:active={tab==='info'} on:click={()=>tab='info'}>基础信息</button><button class="collaboration-refresh ui-icon-button" aria-label="刷新公共产物" on:click={()=>{onRefresh();void refreshArtifacts(selectedID)}}><Icon name="refresh" size={16}/></button></nav>
  {#if error}<p role="alert" class="inline-error">{error}</p>{/if}
  {#if tab==='artifacts'}<PublicArtifacts {collaboration} snapshots={visibleSnapshots} {taskFilter} {onTask}/>
  {:else if tab==='info'}<div class="collaboration-info"><h2>共同目标</h2><p>{collaboration.goal}</p><dl><dt>项目</dt><dd>{folderName(collaboration.repository_path)}</dd><dt>Agent 任务</dt><dd>{collaboration.tasks.length}</dd><dt>创建时间</dt><dd>{new Date(collaboration.created_at).toLocaleString('zh-CN')}</dd></dl></div>
  {:else}<div class="collaboration-activity">{#each activities as task}<button on:click={()=>onTask(task.id)}><span class="activity-node"></span><span><strong>{task.title}</strong><small>{agentName(task.adapter)} · {statusLabels[task.status]}</small></span><time>{new Date(task.updated_at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}</time></button>{/each}{#if !activities.length}<p class="muted">暂无动态</p>{/if}</div>{/if}
 </section><aside class="collaboration-agents" aria-label="协作 Agent 任务"><header><h2>Agent 任务 <span>· {collaboration.tasks.length}</span></h2><button on:click={()=>taskOpen=true}><Icon name="plus" size={16}/>添加</button></header>
 <button class="all-agent-artifacts" class:active={!taskFilter} on:click={()=>taskFilter=''}>查看全部产物 <span>{visibleSnapshots.reduce((n,v)=>n+v.artifacts.length,0)}</span></button>
 {#each pinnedFirst(collaboration.tasks,t=>t.created_at) as task}<article class="agent-task-card" class:selected={taskFilter===task.id}><button class="agent-task-main" on:click={()=>{taskFilter=task.id;tab='artifacts'}}><div><strong>{task.title}</strong><i class="agent-task-dot" class:running={task.status==='running'||task.status==='queued'} class:complete={task.status==='completed'}></i></div><span class="agent-task-description">{task.prompt.slice(0,90)}</span><div class="agent-task-meta"><AgentBadge adapter={task.adapter}/><span>{statusLabels[task.status]}</span></div></button><div class="agent-task-actions"><button class="agent-task-open" on:click={()=>onTask(task.id)} aria-label={`打开任务：${task.title}`}>打开任务 <Icon name="arrow" size={13}/></button><PinButton kind="task" id={task.id} title={task.title} pinned={!!task.pinned_at} disabled={pinning.has(`task:${task.id}`)} {onPin}/><button class="ui-icon-button agent-task-delete" aria-label={`删除指派任务：${task.title}`} on:click={()=>onDelete({kind:'task',id:task.id,title:task.title})}><Icon name="trash" size={15}/></button></div></article>{/each}
 {#if !collaboration.tasks.length}<div class="agent-tasks-empty"><Icon name="plus" size={24}/><button class="subtle-button" on:click={()=>taskOpen=true}>添加任务</button></div>{/if}
 </aside></div>
{:else}<div class="public-loading">{ready?'没有找到这个协作。':'正在读取协作…'}{#if ready}<button class="subtle-button" on:click={()=>onSelect('')}>返回协作列表</button>{/if}</div>{/if}
{#if createOpen}<CollaborationDialog bind:open={createOpen} {project} {agents} onCreated={created}/>{/if}
{#if taskOpen&&collaboration}<CollaborationDialog bind:open={taskOpen} {collaboration} {agents} onTaskCreated={taskCreated}/>{/if}
